-- SQLite schema contract v1.0; all writes are append-only events or projections.
PRAGMA foreign_keys = ON;
CREATE TABLE project(id TEXT PRIMARY KEY, schema_version INTEGER NOT NULL, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE branch(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES project(id), parent_id TEXT REFERENCES branch(id), merge_base_revision TEXT, head_revision TEXT, status TEXT NOT NULL CHECK(status IN ('active','merged','archived')), acl_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE document_node(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES project(id), branch_id TEXT NOT NULL REFERENCES branch(id), parent_id TEXT REFERENCES document_node(id), kind TEXT NOT NULL CHECK(kind IN ('book','volume','act','chapter','scene')), title TEXT NOT NULL, ordinal INTEGER NOT NULL);
CREATE TABLE document_revision(id TEXT PRIMARY KEY, document_node_id TEXT NOT NULL REFERENCES document_node(id), parent_id TEXT REFERENCES document_revision(id), branch_id TEXT NOT NULL REFERENCES branch(id), content_hash TEXT NOT NULL, canonical_text BLOB NOT NULL, created_at TEXT NOT NULL, actor_id TEXT NOT NULL, operation TEXT NOT NULL);
CREATE TABLE event_log(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES project(id), branch_id TEXT NOT NULL REFERENCES branch(id), aggregate_id TEXT NOT NULL, event_type TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, expected_head TEXT, payload_json TEXT NOT NULL, actor_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE deletion_event(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES project(id), branch_id TEXT NOT NULL REFERENCES branch(id), aggregate_id TEXT NOT NULL, revision_id TEXT REFERENCES document_revision(id), reason TEXT NOT NULL, scope TEXT NOT NULL, created_at TEXT NOT NULL, actor_id TEXT NOT NULL);
CREATE TABLE source_span(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES project(id), revision_id TEXT NOT NULL REFERENCES document_revision(id), document_node_id TEXT NOT NULL REFERENCES document_node(id), start_codepoint INTEGER NOT NULL, end_codepoint INTEGER NOT NULL, start_utf8 INTEGER NOT NULL, end_utf8 INTEGER NOT NULL, quote_hash TEXT NOT NULL, quote TEXT NOT NULL, anchor_before TEXT, anchor_after TEXT, status TEXT NOT NULL CHECK(status IN ('valid','stale','ambiguous')));
CREATE TABLE entity(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES project(id), kind TEXT NOT NULL, canonical_name TEXT NOT NULL, aliases_json TEXT NOT NULL DEFAULT '[]', lineage_parent_id TEXT REFERENCES entity(id), status TEXT NOT NULL CHECK(status IN ('active','merged','split','archived')));
CREATE TABLE candidate_memory(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES project(id), branch_id TEXT NOT NULL REFERENCES branch(id), source_span_id TEXT REFERENCES source_span(id), entity_id TEXT REFERENCES entity(id), kind TEXT NOT NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('candidate','accepted','rejected','stale','superseded')), confidence REAL NOT NULL CHECK(confidence >= 0 AND confidence <= 1), created_at TEXT NOT NULL, reviewed_at TEXT, reviewed_by TEXT);
CREATE TABLE ai_run(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES project(id), branch_id TEXT REFERENCES branch(id), mode TEXT NOT NULL, provider TEXT NOT NULL, model TEXT NOT NULL, model_snapshot TEXT, system_prompt_hash TEXT NOT NULL, prompt_hash TEXT NOT NULL, input_hash TEXT NOT NULL, output_hash TEXT, sampling_json TEXT NOT NULL DEFAULT '{}', tool_calls_json TEXT NOT NULL DEFAULT '[]', seed INTEGER, started_at TEXT NOT NULL, ended_at TEXT, status TEXT NOT NULL, error TEXT);
CREATE TABLE merge_conflict(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES project(id), branch_id TEXT NOT NULL REFERENCES branch(id), merge_base TEXT NOT NULL, left_revision TEXT NOT NULL, right_revision TEXT NOT NULL, conflict_type TEXT NOT NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('open','resolved','abandoned')), resolver TEXT, resolved_at TEXT);
CREATE TABLE audit_event(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES project(id), actor_id TEXT NOT NULL, action TEXT NOT NULL, target_id TEXT NOT NULL, before_hash TEXT, after_hash TEXT, reason TEXT, created_at TEXT NOT NULL);
CREATE UNIQUE INDEX idx_event_idempotency ON event_log(idempotency_key);
CREATE INDEX idx_revision_node ON document_revision(document_node_id, created_at);
CREATE INDEX idx_span_revision ON source_span(revision_id, status);
CREATE INDEX idx_candidate_branch_status ON candidate_memory(branch_id, status);
CREATE INDEX idx_ai_run_project_time ON ai_run(project_id, started_at);
